    using var caller = new CancellationTokenSource();
    await ThrowsAsync<OperationCanceledException>(() =>
        CallWithTimeout(ct => { caller.Cancel(); return Never(ct); }, TimeSpan.FromSeconds(30), caller.Token).WaitAsync(TimeSpan.FromSeconds(2)));
