record RetryPolicy(int MaxAttempts, TimeSpan BaseDelay, TimeSpan MaxDelay, TimeSpan Budget, Func<double> Random, Func<TimeSpan, CancellationToken, Task> Delay);

static class Step
{
    public static Func<HttpResponseMessage> Status(int code, int? retryAfterSeconds = null) => () =>
    {
        var response = new HttpResponseMessage((HttpStatusCode)code);
        if (retryAfterSeconds is int s) response.Headers.RetryAfter = new RetryConditionHeaderValue(TimeSpan.FromSeconds(s));
        return response;
    };

    public static Func<HttpResponseMessage> Refused() => () => throw new HttpRequestException("connection refused");
}

/// <summary>Given: plays scripted outcomes and, like HttpClient, refuses to send one message twice. Waits are recorded, not slept.</summary>
sealed class FakeUpstream(params Func<HttpResponseMessage>[] steps)
{
    readonly Queue<Func<HttpResponseMessage>> script = new(steps);
    readonly HashSet<HttpRequestMessage> sent = new();
    public int Calls { get; private set; }
    public List<TimeSpan> Waits { get; } = new();

    public Task<HttpResponseMessage> Send(HttpRequestMessage request, CancellationToken ct)
    {
        if (!sent.Add(request)) throw new InvalidOperationException("The request message was already sent. Cannot send the same request message multiple times.");
        Calls++;
        ct.ThrowIfCancellationRequested();
        return Task.FromResult(script.Dequeue()());
    }

    public Task Delay(TimeSpan wait, CancellationToken ct)
    {
        Waits.Add(wait);
        ct.ThrowIfCancellationRequested();
        return Task.CompletedTask;
    }
}

