// ─────────────────────────────────────────────────────────────────────────
//  02 · retry safe requests within a budget★★★ core
//  concepts: transient statuses · idempotent methods · full jitter · Retry-After · budget
// ─────────────────────────────────────────────────────────────────────────
//
//  Retry only when it can help, only what can be repeated, and only while there is time.

using static Bootcamp.Check;
using System.Net;
using System.Net.Http.Headers;

bool IsTransient(HttpStatusCode status) => (int)status is 408 or 429 or 500 or 502 or 503 or 504;

bool SafeToRepeat(HttpRequestMessage r) =>
    r.Method == HttpMethod.Get || r.Method == HttpMethod.Head || r.Method == HttpMethod.Put
    || r.Method == HttpMethod.Delete || r.Headers.Contains("Idempotency-Key");

TimeSpan Backoff(RetryPolicy p, int failedAttempt)
{
    var exponential = p.BaseDelay * Math.Pow(2, failedAttempt - 1);
    return (exponential < p.MaxDelay ? exponential : p.MaxDelay) * p.Random();
}

async Task<HttpResponseMessage> SendWithRetry(Func<HttpRequestMessage> makeRequest, Func<HttpRequestMessage, CancellationToken, Task<HttpResponseMessage>> send, RetryPolicy policy, CancellationToken ct)
{
    var waited = TimeSpan.Zero;
    for (var attempt = 1; ; attempt++)
    {
        var request = makeRequest();
        HttpResponseMessage? response = null;
        HttpRequestException? failure = null;
        try { response = await send(request, ct); }
        catch (HttpRequestException e) { failure = e; }

        var transient = failure is not null || IsTransient(response!.StatusCode);
        if (!transient || !SafeToRepeat(request) || attempt >= policy.MaxAttempts)
            return response ?? throw failure!;
        var wait = response?.Headers.RetryAfter?.Delta ?? Backoff(policy, attempt);
        if (waited + wait > policy.Budget)
            return response ?? throw failure!;
        response?.Dispose();
        waited += wait;
        await policy.Delay(wait, ct);
    }
}

