        return r;
    }
    var second = await SendWithRetry(Keyed, keyed.Send, Policy(keyed), CancellationToken.None);
    Eq(new object[] { (int)first.StatusCode, bare.Calls, (int)second.StatusCode, keyed.Calls }, new object[] { 503, 1, 201, 2 });
});

Test("Retry-After on a 429 replaces the computed wait", async () =>
{
    var up = new FakeUpstream(Step.Status(429, retryAfterSeconds: 2), Step.Status(200));
    var response = await SendWithRetry(Get, up.Send, Policy(up), CancellationToken.None);
    Eq(new object[] { (int)response.StatusCode, up.Waits }, new object[] { 200, new[] { TimeSpan.FromSeconds(2) } });
});

Test("the budget allows waits that add up to it exactly, and stops the next one (boundary)", async () =>
{
    var up = new FakeUpstream(Step.Status(503), Step.Status(503), Step.Status(503), Step.Status(200));
    var response = await SendWithRetry(Get, up.Send, Policy(up, attempts: 4, budgetMs: 150), CancellationToken.None);
    Eq(new object[] { (int)response.StatusCode, up.Calls, up.Waits }, new object[] { 503, 3, new[] { Ms(50), Ms(100) } });
});

Test("connection failures are retried, and the last one reaches the caller", async () =>
{
    var up = new FakeUpstream(Step.Refused(), Step.Refused(), Step.Refused());
    await ThrowsAsync<HttpRequestException>(() => SendWithRetry(Get, up.Send, Policy(up), CancellationToken.None), "connection refused");
    Eq(new object[] { up.Calls, up.Waits }, new object[] { 3, new[] { Ms(50), Ms(100) } });
});

Test("a caller that cancels is never retried", async () =>
{
    using var cts = new CancellationTokenSource();
    var up = new FakeUpstream(() => { cts.Cancel(); return new HttpResponseMessage(HttpStatusCode.ServiceUnavailable); }, Step.Status(200));
    await ThrowsAsync<OperationCanceledException>(() => SendWithRetry(Get, up.Send, Policy(up), cts.Token));
    Eq(up.Calls, 1);
});

// ──────────────────────────── types ──────────────────────────────────────

record RetryPolicy(int MaxAttempts, TimeSpan BaseDelay, TimeSpan MaxDelay, TimeSpan Budget, Func<double> Random, Func<TimeSpan, CancellationToken, Task> Delay);

static class Step
{
    public static Func<HttpResponseMessage> Status(int code, int? retryAfterSeconds = null) => () =>
    {
        var response = new HttpResponseMessage((HttpStatusCode)code);
        if (retryAfterSeconds is int s) response.Headers.RetryAfter = new RetryConditionHeaderValue(TimeSpan.FromSeconds(s));
        return response;
    };

    public static Func<HttpResponseMessage> Refused() => () => throw new HttpRequestException("connection refused");
}

/// <summary>Given: plays scripted outcomes and, like HttpClient, refuses to send one message twice. Waits are recorded, not slept.</summary>
sealed class FakeUpstream(params Func<HttpResponseMessage>[] steps)
{
    readonly Queue<Func<HttpResponseMessage>> script = new(steps);
    readonly HashSet<HttpRequestMessage> sent = new();
    public int Calls { get; private set; }
    public List<TimeSpan> Waits { get; } = new();

    public Task<HttpResponseMessage> Send(HttpRequestMessage request, CancellationToken ct)
    {
        if (!sent.Add(request)) throw new InvalidOperationException("The request message was already sent. Cannot send the same request message multiple times.");
        Calls++;
        ct.ThrowIfCancellationRequested();
        return Task.FromResult(script.Dequeue()());
    }

    public Task Delay(TimeSpan wait, CancellationToken ct)
    {
        Waits.Add(wait);
        ct.ThrowIfCancellationRequested();
        return Task.CompletedTask;
    }
}

fund-csharp/22-httpclient-timeouts-retri.explanation:
Classify the outcome, then check the three conditions before waiting:

```csharp
var request = makeRequest();                       // a fresh message every attempt
try { response = await send(request, ct); }
catch (HttpRequestException e) { failure = e; }
var transient = failure is not null || IsTransient(response!.StatusCode);
if (!transient || !SafeToRepeat(request) || attempt >= policy.MaxAttempts) return response ?? throw failure!;
var wait = response?.Headers.RetryAfter?.Delta ?? Backoff(policy, attempt);
if (waited + wait > policy.Budget) return response ?? throw failure!;
response?.Dispose();
waited += wait;
await policy.Delay(wait, ct);
```

`Backoff` is `min(MaxDelay, BaseDelay x 2^(attempt-1)) x Random()`. The tests catch the usual wrong loops: retrying every non-2xx (the 404 is sent twice), retrying a bare POST (the payment is sent twice), a fixed or un-jittered delay (the recorded waits differ), `>=` in the budget check (the exact-budget case stops one wait early), reusing one request message (the fake refuses it the way `SendAsync` does), and and a wait that ignores the caller's token or swallows its cancellation (the cancelled caller is called a second time).
